        aggregated[sku] = aggregated.get(sku, Decimal('0')) + amount

    result = {}
    for sku in sorted(aggregated):
        result[sku] = str(aggregated[sku].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

